<?php
$MOD = 998244353;

fscanf(STDIN, "%d %d %d", $p, $s, $r);

// ---------- modular pow ----------
function modpow($base, $exp, $mod) {
    $result = 1;
    $base %= $mod;
    if ($base < 0) $base += $mod;
    while ($exp > 0) {
        if ($exp & 1) $result = ($result * $base) % $mod;
        $base = ($base * $base) % $mod;
        $exp >>= 1;
    }
    return $result;
}

// ---------- precompute factorials ----------
$MAXN = $s + $p + 20; // safety buffer
$fact = array_fill(0, $MAXN + 1, 1);
for ($i = 1; $i <= $MAXN; $i++) {
    $fact[$i] = ($fact[$i - 1] * $i) % $MOD;
}
$invfact = array_fill(0, $MAXN + 1, 1);
$invfact[$MAXN] = modpow($fact[$MAXN], $MOD - 2, $MOD);
for ($i = $MAXN - 1; $i >= 0; $i--) {
    $invfact[$i] = ($invfact[$i + 1] * ($i + 1)) % $MOD;
}

function C($n, $k) {
    global $fact, $invfact, $MOD;
    if ($n < 0 || $k < 0 || $k > $n) return 0;
    return ($fact[$n] * $invfact[$k] % $MOD) * $invfact[$n - $k] % $MOD;
}

// ways to have n variables each in [0, maxVal], summing to total
function ways($n, $maxVal, $total) {
    global $MOD;
    if ($total < 0) return 0;
    if ($n == 0) {
        return ($total == 0) ? 1 : 0;
    }
    if ($maxVal < 0) {
        return 0; // n>0 but no allowed values
    }
    $res = 0;
    $step = $maxVal + 1;
    for ($j = 0; $j <= $n; $j++) {
        $rem = $total - $j * $step;
        if ($rem < 0) break;
        $term = C($n, $j) * C($rem + $n - 1, $n - 1) % $MOD;
        if ($j % 2 == 1) {
            $term = ($MOD - $term) % $MOD;
        }
        $res = ($res + $term) % $MOD;
    }
    return $res;
}

$m = $p - 1;

// precompute inverse of numbers 1..(m+1)
$invNum = array_fill(0, $m + 2, 1);
for ($i = 1; $i <= $m + 1; $i++) {
    $invNum[$i] = modpow($i, $MOD - 2, $MOD);
}

// ---------- numerator ----------
$num = 0;
for ($v = $r; $v <= $s; $v++) {
    for ($t = 0; $t <= $m; $t++) {
        $rem = $s - $v * ($t + 1);
        if ($rem < 0) {
            // if v > 0, increasing t only decreases rem further -> break
            if ($v > 0) break;
            else continue; // v == 0, rem stays same for all t (should not be negative here)
        }
        $remPlayers = $m - $t;
        $w = ways($remPlayers, $v - 1, $rem);
        if ($w == 0) continue;
        $term = C($m, $t) * $w % $MOD;
        $term = $term * $invNum[$t + 1] % $MOD;
        $num = ($num + $term) % $MOD;
    }
}

// ---------- denominator ----------
$den = 0;
if ($m == 0) {
    $den = 1;
} else {
    for ($v = $r; $v <= $s; $v++) {
        $rem = $s - $v;
        $den = ($den + C($rem + $m - 1, $m - 1)) % $MOD;
    }
}

$ans = $num * modpow($den, $MOD - 2, $MOD) % $MOD;

echo $ans . "\n";
